    13	
    14	namespace acommon {
    15	
    16	  struct MutableString {
    17	    char * str;
    18	    unsigned int size;
    19	
    20	    MutableString() : str(0), size(0) {}
    21	    MutableString(char * str0) : str(str0), size(strlen(str)) {}
    22	    MutableString(char * str0, unsigned int sz) : str(str0), size(sz) {}
    23	
    24	    bool empty() const {return size == 0;}
    25	    operator char * () const {return str;}
    26	    operator ParmString () const {return ParmString(str, size);}
    27	    char * begin() const {return str;}
    28	    char * end() const {return str + size;}
    29	  };
    30	
    31	  static inline bool operator==(MutableString s1, MutableString s2)
    32	  {
    33	    if (s1.size != s2.size)
    34	      return false;
    35	    else
    36	      return memcmp(s1,s2,s1.size) == 0;
    37	  }
    38	  static inline bool operator==(const char * s1, MutableString s2)
    39	  {
    40	    if ( s1 == NULL ) {
    41	      return s2.size == 0;
    42	    }
    43	    return strcmp(s1,s2) == 0;
    44	  }
    45	  static inline bool operator==(MutableString s1, const char * s2)
    46	  {
    47	    if ( s2 == NULL ) {
    48	      return s1.size == 0;
    49	    }
    50	    return strcmp(s1,s2) == 0;
    51	  }
